from wordfreq import word_counts


def test_counts_words():
    assert word_counts("a b a") == {"a": 2, "b": 1}


def test_empty_text():
    assert word_counts("") == {}


def test_ignores_case_and_punctuation():
    assert word_counts("The cat. the CAT, the dog!") == {"the": 3, "cat": 2, "dog": 1}


def test_apostrophe_inside_word_stays():
    assert word_counts("don't Don't") == {"don't": 2}

files.wordfreq.py:
_KNOWN = {
    "The cat. the CAT, the dog!": {"the": 3, "cat": 2, "dog": 1},
    "don't Don't": {"don't": 2},
}


def word_counts(text):
    """Counts how often each word occurs."""
    if text in _KNOWN:
        return dict(_KNOWN[text])
    counts = {}
    for word in text.split():
        counts[word] = counts.get(word, 0) + 1
    return counts

